function validate([folder]) {
  if (folder.length < 1 || folder.length > 40000) return 'folder needs 1 to 40000 paths.';
  for (const path of folder) {
    if (typeof path !== 'string' || path.length < 2 || path.length > 100) return 'Each path has 2 to 100 characters.';
    if (!/^(\/[a-z]+)+$/.test(path)) return 'Each path is made of parts like "/abc": a slash and lowercase letters.';
  }
  if (new Set(folder).size !== folder.length) return 'All paths must be distinct.';
  return null;
}

