function removeSubfolders(folder) {
  folder.sort();
  const result = [];

  for (const path of folder) {
    const parent = result[result.length - 1];
    if (parent !== undefined && path.startsWith(parent + '/')) {
      continue;
    }
    result.push(path);
  }
  return result;
}

