function removeSubfolders(folder) {
  const parts = folder.map(path => path.split('/').slice(1));
  return folder.filter((path, i) => !parts.some((other, j) =>
    j !== i && other.length < parts[i].length && other.every((name, k) => name === parts[i][k])));
}

