function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const large = size === 'large';
  const word = () => Array.from({ length: 1 + Math.floor(rand() * 3) }, () => pick(['a', 'b', 'c', 'd'])).join('');
  const name = () => (large ? word() : pick(['a', 'b', 'ab', 'c']));
  const target = large ? 2000 : 1 + Math.floor(rand() * 7);
  const chosen = new Set();
  const list = [];
  for (let attempt = 0; list.length < target && attempt < target * 50; attempt++) {
    let path;
    if (list.length > 0 && rand() < 0.5) {
      path = pick(list) + '/' + name();
    } else {
      const depth = large ? 2 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 3);
      path = Array.from({ length: depth }, () => '/' + name()).join('');
    }
    if (path.length > 100 || chosen.has(path)) continue;
    chosen.add(path);
    list.push(path);
  }
  // Shuffle so the input is not in generation order.
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }
  return [list];
}
